(()=>{
'use strict';
const D=window.CARE_STORY,game=new window.CareGame(D),$=id=>document.getElementById(id),T=D.T;
const locales=['th','zh','en'];let prefs={lang:'th',name:'',look:0,outfit:0,pace:25,fontScale:100,music:true,effects:true};
try{const p=JSON.parse(localStorage.getItem('heart-of-care-prefs-v1')||'{}');prefs={...prefs,...p};}catch{}
if(!locales.includes(prefs.lang))prefs.lang='th';if(![15,25,45].includes(+prefs.pace))prefs.pace=25;if(![0,1].includes(+prefs.look))prefs.look=0;if(![0,1,2].includes(+prefs.outfit))prefs.outfit=0;prefs.name=String(prefs.name||'').slice(0,100);
let paused=false,lastTick=performance.now(),choiceOrder=[],renderedNodeId=null,announcedTen=false;
if(![100,125,150,175,200].includes(+prefs.fontScale))prefs.fontScale=100;
function applyTextSize(){document.documentElement.style.setProperty('--text-scale',String(+prefs.fontScale/100));document.documentElement.dataset.largeText=+prefs.fontScale>=150?'true':'false';$('text-size').value=String(prefs.fontScale);}
const tr=value=>typeof value==='string'?value:value?.[prefs.lang]||value?.en||'';
const txt=(th,zh,en)=>tr(T(th,zh,en));
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ui=k=>tr(D.ui[k]);
const audio=new window.CareAudio();
prefs.music=prefs.music!==false;prefs.effects=prefs.effects!==false;
audio.configure(prefs.music,prefs.effects);
function renderAudio(){for(const [id,key,label,symbol] of [['music-toggle','music',txt('ดนตรี','音樂','Music'),'♪'],['effects-toggle','effects',txt('เอฟเฟกต์','音效','Effects'),'♫']]){const el=$(id);el.textContent=symbol+' '+label+': '+(prefs[key]?txt('เปิด','開','On'):txt('ปิด','關','Off'));el.setAttribute('aria-pressed',String(prefs[key]));}}
for(const key of ['music','effects'])$(key+'-toggle').addEventListener('click',()=>{prefs[key]=!prefs[key];audio.configure(prefs.music,prefs.effects);audio.unlock();savePrefs();renderAudio();});
document.addEventListener('pointerdown',()=>audio.unlock(),{once:true});
document.addEventListener('keydown',()=>audio.unlock(),{once:true});
function playAnswer(){const h=game.state.history.at(-1);if(h)audio.answer(h.correctness,h.timeout);}

let selectedRun=null,historyBusy=false,historyNotice='';
let starting=false,accountState='ready';
function renderAccount(){$('start-game').disabled=starting;$('account-message').textContent=starting?ui('participantStarting'):accountState==='error'?ui('participantError'):'';}
const history=new window.CARE_HISTORY.History(()=>{renderSaveStatus();});
function renderSaveStatus(){const el=$('save-status');if(!el)return;el.textContent=history.state==='idle'?'':ui(history.state==='saving'?'saving':history.state==='saved'?'saved':history.state==='offline'?'historyOffline':'saveFailed');el.classList.toggle('save-error',history.state==='error');}
const emotionLabel=m=>ui({smile:'warm',concern:'worried',surprise:'surprised',neutral:'neutral'}[m]||'neutral');
function captureLog(){const h=game.state.history.at(-1);if(h&&!h.language){h.language=prefs.lang;h.promptRendered=$('dialogue-text').textContent;}history.capture(game,prefs,choiceOrder);}
function dateLabel(value){try{return new Intl.DateTimeFormat(prefs.lang==='zh'?'zh-TW':prefs.lang,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}catch{return value||'';}}
function renderHistory(){
 const all=history.sessions,s=all.find(x=>x.id===selectedRun)||all[0];selectedRun=s?.id||null;
 $('history-message').textContent=historyBusy?ui('historyLoading'):historyNotice?ui(historyNotice):!history.online?ui('historyOffline'):all.length?'':ui('historyEmpty');
 $('history-list').innerHTML=all.map(run=>`<button class="run-card ${run.id===selectedRun?'selected':''}" data-run="${escape(run.id)}"><strong>${escape(run.name)}</strong><span>${escape(dateLabel(run.startedAt))}</span><small>${ui(run.status==='completed'?'completedRun':'inProgress')} · ${run.answers.length} ${ui('answered')}</small></button>`).join('');
 document.querySelectorAll('[data-export="all"]').forEach(b=>b.disabled=historyBusy||!all.some(r=>r.answers.length));
 if(!s){$('history-detail').innerHTML='';return;}
 const safety=s.result?.safety??s.answers.at(-1)?.safetyAfter??50,k=s.result?.knowledge||s.knowledge;
 $('history-detail').innerHTML=`<div class="run-heading"><h3>${escape(s.name)}</h3><small>${escape(dateLabel(s.startedAt))} · ${ui(s.status==='completed'?'completedRun':'inProgress')}</small></div><div class="history-scores"><span>${ui('safety')} <strong>${safety}</strong></span><span>${ui('knowledge')} <strong>${k.correct}/${k.total}</strong></span><span>${ui('answered')} <strong>${s.answers.length}</strong></span></div><div class="history-actions"><span>${ui('exportThis')}</span><button class="secondary-btn" data-export="this" data-format="csv" ${s.answers.length?'':'disabled'}>CSV</button><button class="secondary-btn" data-export="this" data-format="json" ${s.answers.length?'':'disabled'}>JSON</button></div>${s.answers.length?s.answers.map((a,i)=>`<details class="answer-log"><summary><span>${i+1}. ${escape(a.chapter)}</span><small class="${a.correctness===2?'answer-good':'answer-review'}">${a.timeout?ui('responseExpired'):ui(a.correctness===2?'correct':a.correctness===1?'safeBlunt':'incorrect')} · ${a.elapsedSeconds.toFixed(1)}s · ${emotionLabel(a.emotion)}</small></summary><p class="log-question">${escape(a.prompt)}</p><p><strong>${ui('chosenAnswer')}:</strong> ${escape(a.choice)}</p><p class="review-answer"><strong>${ui('correctAnswer')}:</strong> ${escape(a.correctAnswer)}</p><p>${escape(a.reaction)} ${escape(a.explanation)}</p><p class="log-lesson">${escape(a.lesson)}</p><div class="log-metadata">${ui('answeredAt')}: ${escape(dateLabel(a.answeredAt))} · ${ui('answerTime')}: ${a.elapsedSeconds.toFixed(1)} / ${a.budget}s<br>${ui('safety')}: ${a.safetyAfter} · ${ui('trust')}: ${a.trustAfter} · ${ui('tension')}: ${a.stressAfter}</div>${a.sources.map(x=>`<a href="${escape(x.url)}" target="_blank" rel="noopener noreferrer">${escape(x.title)}</a>`).join('')}</details>`).join(''):`<p>${ui('noReplies')}</p>`}`;
}
async function loadHistory(){historyBusy=true;historyNotice='';renderHistory();try{await history.flush();await history.loadAll();}catch{historyNotice='historyError';const all=new Map(history.sessions.map(r=>[r.id,r]));for(const [id,r]of history.snapshots)all.set(id,r);history.sessions=[...all.values()].sort((a,b)=>b.startedAt.localeCompare(a.startedAt));}finally{historyBusy=false;renderHistory();}}
function openHistory(){openDialog('history-dialog');loadHistory();}
function exportRuns(scope,format){const sessions=scope==='this'?history.sessions.filter(s=>s.id===selectedRun):history.sessions;if(!sessions.some(s=>s.answers.length)){$('history-message').textContent=ui('noExport');return;}const payload=format==='csv'?window.CARE_HISTORY.csv(sessions):JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),sessions},null,2);const blob=new Blob([payload],{type:format==='csv'?'text/csv;charset=utf-8':'application/json;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Heart-of-Care-${scope==='this'?'run':'all'}-${new Date().toISOString().slice(0,10)}.${format}`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function savePrefs(){try{localStorage.setItem('heart-of-care-prefs-v1',JSON.stringify(prefs));}catch{}}
function openDialog(id){if(!$(id).open)$(id).showModal();lastTick=performance.now();}
function blocked(){return paused||document.hidden||[...document.querySelectorAll('dialog')].some(d=>d.open);}
function setSprite(el,npc,mood){el.style.backgroundImage=`url('assets/${npc}-${mood}.webp')`;el.style.backgroundSize='contain';el.style.backgroundPosition='center';}
function renderAvatar(){const ids=['player-mini','player-preview'];if(game.state.phase==='start')ids.push('cast-sprite');for(const id of ids){const el=$(id);el.style.backgroundImage=`url('assets/player-${prefs.look}-${prefs.outfit}.webp')`;el.style.backgroundSize='contain';el.style.backgroundPosition='center';el.setAttribute('aria-label',txt('ตัวละครเภสัชกรของคุณ','你的藥師角色','Your pharmacist character')+' · '+ui(['coat','scrubs','cardigan'][prefs.outfit]));}$('player-name-display').textContent=prefs.name;}
function renderSetup(){
 $('pace-options').innerHTML=[45,25,15].map((n,i)=>`<button type="button" class="pace-option ${+prefs.pace===n?'selected':''}" data-pace="${n}" aria-pressed="${+prefs.pace===n}"><strong>${n}s</strong>${ui(['slow','standard','busy'][i])}</button>`).join('');
 $('appearance-options').innerHTML=[0,1].map(i=>`<button type="button" data-look="${i}" class="${+prefs.look===i?'selected':''}" aria-pressed="${+prefs.look===i}">${ui(i?'lookB':'lookA')}</button>`).join('');
 $('outfit-options').innerHTML=['coat','scrubs','cardigan'].map((k,i)=>`<button type="button" data-outfit="${i}" class="${+prefs.outfit===i?'selected':''}" aria-pressed="${+prefs.outfit===i}"><span class="outfit-swatch" aria-hidden="true" style="background:${['#fff','#25446d','#60a2a5'][i]}"></span>${ui(k)}</button>`).join('');
 renderAvatar();
}
function renderStatic(){
 applyTextSize();renderAudio();
 document.documentElement.lang=prefs.lang==='zh'?'zh-Hant':prefs.lang;
 document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(k==='startTitle')el.innerHTML=ui(k);else el.textContent=ui(k);});
 $('language').value=prefs.lang;$('language').setAttribute('aria-label',ui('language'));$('player-name-input').value=prefs.name;$('pause-button').setAttribute('aria-label',ui('pause'));document.querySelectorAll('.close-btn').forEach(el=>el.setAttribute('aria-label',ui('close')));$('game').setAttribute('aria-label',txt('เกมบทสนทนาเภสัชกร','藥師對話遊戲','Pharmacist dialogue game'));
 $('student-code-input').value=prefs.studentCode||'';$('study-group-input').value=prefs.group||'';renderAccount();$('history-open').setAttribute('aria-label',ui('historyTitle'));renderSetup();renderCase();renderReferences();renderSaveStatus();if($('history-dialog').open)renderHistory();
}
function renderCase(){
 const heading=txt('ภาพรวม','個案概況','Overview');
 const overview=txt('คุณหลิน อายุ 76 ปี มี Alzheimer’s, กลืนลำบากเรื้อรัง, ไทรอยด์ต่ำ, ความดันโลหิตสูง, ซึมเศร้า และ GERD มาโรงพยาบาลเพราะไข้ ไอมีเสมหะ หายใจลำบาก และสำลักซ้ำ ทีมสงสัยปอดอักเสบจากการสำลัก','林先生 76 歲，有阿茲海默症、慢性吞嚥困難、甲狀腺低下、高血壓、憂鬱症及 GERD。因發燒、有痰咳嗽、呼吸困難及反覆嗆咳就醫，團隊懷疑吸入性肺炎。','Mr. Lin, 76, has Alzheimer’s disease, chronic dysphagia, hypothyroidism, hypertension, depression, and GERD. He presents with fever, productive cough, dyspnea, and recurrent choking. The team suspects aspiration pneumonia.');
 const home=txt('ลูกสาวดูแลคนเดียว บดยารวมกับโยเกิร์ต ให้ levothyroxine พร้อมอาหาร และผู้ป่วยมักนอนหลังมื้ออาหาร','女兒獨自照顧，將藥磨碎混入優格，Levothyroxine 隨餐給，病人常在飯後躺下。','His daughter is the sole caregiver. She crushes medicines into yogurt and gives levothyroxine with meals. He often lies down after meals.');
 const medrows=[['Donepezil','10 mg',txt('วันละครั้ง · เม็ดเคลือบฟิล์ม','每日一次 · 膜衣錠','Once daily · film-coated tablet')],['Memantine','10 mg',txt('วันละ 2 ครั้ง · เม็ดเคลือบฟิล์ม','每日兩次 · 膜衣錠','Twice daily · film-coated tablet')],['Sertraline','50 mg',txt('วันละครั้ง · เม็ดเคลือบฟิล์ม','每日一次 · 膜衣錠','Once daily · film-coated tablet')],['Losartan','25 mg',txt('วันละ 2 ครั้ง · เม็ดเคลือบฟิล์ม','每日兩次 · 膜衣錠','Twice daily · film-coated tablet')],['Levothyroxine','50 mcg',txt('วันละครั้ง · ยาเม็ด','每日一次 · 錠劑','Once daily · tablet')]];
 const labrows=[['Temperature','38.2 → 37.8 °C'],['SpO₂','92 → 95 %'],['WBC','12.2 → 10.8 ×10³/µL'],['CRP','16.3 → 11.9 mg/dL'],['Creatinine','0.81 → 0.80 mg/dL'],['TSH','4.1 mIU/L'],['Free T4','0.77 ng/dL']];
 $('case-content').innerHTML=`<h3>${heading}</h3><p>${overview}</p><h3>${txt('การดูแลที่บ้าน','居家照護','Care at home')}</h3><p>${home}</p><h3>${txt('ยาประจำในเคสต้นฉบับ','原個案的長期用藥','Chronic medicines in the source case')}</h3><table><thead><tr><th>${txt('ยา','藥物','Medicine')}</th><th>${txt('ขนาด','劑量','Dose')}</th><th>${txt('รูปแบบ / เวลา','劑型／時間','Form / timing')}</th></tr></thead><tbody>${medrows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="modal-note">${txt('ทีมให้ ampicillin–sulbactam IV ในเคสนี้ เกมไม่ได้ใช้ให้เลือกขนาดยาแทนผู้สั่งยา และไม่มีข้อมูลผลิตภัณฑ์จริงครบถ้วน','本個案使用 Ampicillin–sulbactam IV。遊戲不要求替處方者選劑量，且未提供完整實際產品資料。','The source case uses IV ampicillin–sulbactam. This game does not ask you to replace the prescriber’s dosing decision; full product details are not provided.')}</p><h3>${txt('แนวโน้มข้อมูลเคส: 19 → 20 ม.ค.','個案趨勢：1/19 → 1/20','Case trends: January 19 → 20')}</h3><table><tbody>${labrows.map(r=>`<tr><th>${r[0]}</th><td>${r[1]}</td></tr>`).join('')}</tbody></table><div class="notice">${ui('notesPause')}<br>${ui('learningMode')}</div><button class="subtle-button" id="notes-reference">${ui('references')}</button>`;
}
function renderReferences(){
 const refList=Object.entries(D.sources).map(([key,s])=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)}</a><small>${key==='original'?txt('ข้อมูลเคสต้นทาง · CC BY-NC-SA 4.0','個案來源 · CC BY-NC-SA 4.0','Source teaching case · CC BY-NC-SA 4.0'):txt('ใช้ตรวจคำอธิบายเรื่องยาและการดูแล','用於核對用藥與照護說明','Used to check medication and care explanations')}</small></li>`).join('');
 $('reference-content').innerHTML=`<p>${txt('ดัดแปลงข้อมูลเคสจาก Pharmacist Clinical Training Simulator – Dysphagia โดย Huu Hiep Tran, Professor 陳崇鈺 Research Team, Kaohsiung Medical University ตัวละคร บทสนทนา คะแนน เวลา และตอนจบสร้างใหม่เพื่อเกมนี้','個案改編自 Huu Hiep Tran、Professor 陳崇鈺 Research Team（高雄醫學大學）的 Pharmacist Clinical Training Simulator – Dysphagia。角色、對話、分數、時間與結局為本遊戲新創。','Adapted from Pharmacist Clinical Training Simulator – Dysphagia by Huu Hiep Tran, Professor 陳崇鈺 Research Team, Kaohsiung Medical University. Characters, dialogue, scores, timing, and endings are new fictional game elements.')}</p><div class="notice">${ui('learningMode')}<br>${ui('scoreNote')}</div><h3>${txt('สิ่งที่ปรับจากเฉลยเดิม','相較原解答的調整','Changes from the original answer key')}</h3><ul><li>${txt('ไม่ใช้กฎว่า sertraline เม็ดต้องให้กับน้ำผลไม้เปรี้ยวทุกครั้ง และไม่สรุปว่าโยเกิร์ตทำให้ยาล้มเหลวจากข้อมูลนี้เพียงอย่างเดียว','不使用「Sertraline 錠一定要搭配酸性果汁」的通則，也不僅憑本個案就斷定優格造成藥物失效。','No blanket rule requiring acidic juice for sertraline tablets, and no conclusion that yogurt caused treatment failure from these case facts alone.')}</li><li>${txt('เลือกวิธีให้ตามผลิตภัณฑ์จริงและแผนการกลืน ไม่ถือว่ายาน้ำปลอดภัยเสมอ','依實際產品與吞嚥計畫選擇給法，不假設液態一定安全。','Administration depends on the product and swallowing plan; liquids are not automatically safe.')}</li><li>${txt('ไม่ใช้ CRP เพียงตัวเดียวกำหนดวันหยุดยาปฏิชีวนะ และไม่สรุปว่าอาการทางสมองเกิดจากยาเพียงสาเหตุเดียว','不只依 CRP 決定停抗生素日期，也不把認知變化歸因於單一用藥問題。','CRP alone does not decide antibiotic duration. Cognitive changes are not attributed to one medication issue alone.')}</li></ul><h3>${txt('แหล่งตรวจสอบ','核對來源','References')}</h3><ul class="source-list">${refList}</ul><p class="modal-note">${txt('ดัดแปลงและเผยแพร่ภายใต้ CC BY-NC-SA 4.0 · สำหรับใช้โดยไม่แสวงหากำไร · ตรวจสอบแหล่งข้อมูล 1 ตุลาคม 2026 · ภาษา Mandarin ใช้อักษรจีนตัวเต็ม','改編作品採 CC BY-NC-SA 4.0 · 非商業用途 · 資料核對日期：2026 年 10 月 1 日 · 中文採繁體字','Adaptation licensed CC BY-NC-SA 4.0 · noncommercial use · sources checked October 1, 2026 · Mandarin uses Traditional Chinese.')}</p><p class="modal-note">${ui('cloudHistory')}</p>`;
 const extra=[
  txt('คำถามพี่เลี้ยงแยก ionization, dissolution และการดูดซึม; ตัวอย่าง pKa = 8 เป็นตัวเลขสมมติ ไม่ใช่ pKa ที่ระบุให้ sertraline','前輩題目區分離子化、溶解與吸收；pKa = 8 是假設值，不是 Sertraline 的指定值。','The debrief distinguishes ionization, dissolution, and absorption. The pKa = 8 example is hypothetical, not a stated sertraline value.'),
  txt('PPI และ antipsychotic เป็นคำถามสมมติต่อยอด ไม่ได้เพิ่มยาเข้าในรายการคุณหลิน การทบทวนยาอาศัยข้อบ่งใช้และประโยชน์/ความเสี่ยง','PPI 和抗精神病藥是延伸假設，沒有加入林先生藥單；用藥評估需看適應症與利弊。','PPI and antipsychotic questions are hypothetical extensions, not additions to Mr. Lin’s medicine list. Review indication and benefit–risk.'),
  txt('ไม่แนะนำ chlorhexidine ป้องกัน AP เป็น routine ทุกราย และไม่เปลี่ยน losartan เป็น ACE inhibitor อัตโนมัติ; อธิบายบริบทและข้อจำกัดของหลักฐานหลังตอบ','不建議人人常規用 Chlorhexidine 預防 AP，也不自動把 Losartan 換成 ACE 抑制劑；解答說明證據情境與限制。','No universal routine chlorhexidine prevention or automatic losartan-to-ACE switch. Feedback explains the evidence context and limits.')
 ];$('reference-content').querySelector('ul').insertAdjacentHTML('beforeend',extra.map(v=>`<li>${escape(v)}</li>`).join(''));
}
function moodFor(npc){const s=game.state,p=s.people[npc];if(s.phase==='feedback'&&s.feedback.node.npc===npc)return s.expressions[npc];return p.stress>=74||p.trust<30?'concern':s.expressions[npc]||(p.trust>=58&&p.stress<55?'smile':'neutral');}
function renderMeta(){
 const s=game.state,n=s.phase==='ending'?D.nodes[D.nodes.length-1]:game.node(),scene=n?.scene||0;
 $('chapters').innerHTML=D.scenes.map((c,i)=>`<li class="${i===scene?'active':i<scene?'done':''}"><span class="chapter-number">${i<scene?'✓':String(i+1).padStart(2,'0')}</span><span>${tr(c.title)}</span></li>`).join('');
 $('scene-index').textContent=`${String(scene+1).padStart(2,'0')} / ${String(D.scenes.length).padStart(2,'0')}`;$('scene-title').textContent=tr(D.scenes[scene].title);$('location').textContent=tr(D.scenes[scene].location);$('shift-clock').textContent=D.scenes[scene].clock;
 $('safety-value').textContent=s.safety;$('safety-fill').style.width=s.safety+'%';
 $('progress-label').textContent=s.phase==='start'?ui('ready'):s.phase==='ending'?ui('completed'):`${txt('ฉาก','場景','Scene')} ${scene+1} / ${D.scenes.length}`;
 $('knowledge-card').hidden=!s.caseResult;$('knowledge-value').textContent=`${s.knowledge.correct} / ${s.knowledge.total}`;$('knowledge-fill').style.width=(100*s.knowledge.correct/s.knowledge.total)+'%';$('knowledge-progress').textContent=`${txt('ตอบแล้ว','已回答','Answered')} ${s.knowledge.answered} / ${s.knowledge.total} · ${ui('knowledgeHint')}`;
 if(s.phase==='start'){renderAvatar();return;}
 if(n){const p=s.people[n.npc],m=moodFor(n.npc);setSprite($('cast-sprite'),n.npc,m);$('cast-sprite').dataset.emotion=m;$('cast-sprite').setAttribute('aria-label',ui(n.npc+'Name')+' · '+emotionLabel(m));$('npc-name').textContent=ui(n.npc+'Name');$('npc-mood').textContent=emotionLabel(m);$('mood-card').dataset.emotion=m;$('mood-symbol').textContent=m==='smile'?'♥':m==='surprise'?'!?':'♡';$('trust-value').textContent=p.trust+'/100';$('trust-fill').style.width=p.trust+'%';$('stress-value').textContent=p.stress+'/100';$('stress-fill').style.width=p.stress+'%';}
}
function shuffle(n){const a=Array.from({length:n},(_,i)=>i);for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function emotionText(n){
 const p=game.state.people[n.npc];
 if(n.id==='mentor-briefing')return prefs.name+' · '+tr(n.text);
 if(n.id==='mentor-return'){const c=game.state.caseResult;return txt('กลับมาแล้ว '+prefs.name+' พี่เห็นบันทึกเคสแล้ว ','回來了，'+prefs.name+'。我看過個案紀錄了。','Welcome back, '+prefs.name+'. I’ve read the case notes. ')+(c?.id==='review'?txt('ทีมยังต้องทบทวนความเสี่ยงก่อนใช้แผนกลับบ้าน เราจะคุยเหตุผลเรื่องยาเพื่อเตรียมแก้แผนไปด้วยกัน','出院計畫的風險仍需團隊確認。一起討論藥學理由，準備修正計畫。','The discharge plan still needs a team safety review. Let’s discuss the pharmacology as we prepare to revise it.'):txt('ขั้นต่อไปมาลองอธิบายว่าเหตุผลทางยาที่อยู่หลังแผนคืออะไร พี่ถามทีละประเด็นนะ','接著一起說明計畫背後的藥學理由，一次一個重點。','Now let’s explain the pharmacology behind the plan, one point at a time.'));}
 if(n.id==='disclosure'&&p.trust<35)return txt('ฉันกลัวคุณจะตำหนิค่ะ… ฉันบดยารวมกับโยเกิร์ต เพราะไม่รู้จะทำอย่างไรดี','我怕你會責備我……我把藥一起磨進優格，因為不知道該怎麼做。','I’m afraid you’ll blame me… I crush the tablets into yogurt because I don’t know what else to do.');
 if(n.id==='handoff'&&p.trust>=70)return txt('ผมเชื่อการประเมินของคุณครับ ก่อนให้กลับ ขอแผนส่งต่อสั้น ๆ ที่ทีมใช้ต่อได้','我信任你的評估。出院前，請整理團隊能直接使用的精簡交班計畫。','I trust your assessment. Before discharge, could you give us a short handoff the team can use?');
 if(n.id==='final'&&p.trust<30)return txt('เรายังไม่ค่อยเข้าใจตรงกันครับ ถ้าแผนการกลืนหรือวิธีให้ยายังไม่ยืนยัน คุณจะทำอย่างไร?','我們還沒完全取得共識。如果吞嚥計畫或給藥方式尚未確認，你會怎麼做？','We still seem to be on different pages. If the swallowing or administration plan is unconfirmed, what will you do?');
 return tr(n.text);
}
function renderTimer(){const s=game.state,active=s.phase==='choice';$('countdown').hidden=!active;$('timer-track').hidden=!active;const left=Math.ceil(s.remaining);$('seconds').textContent=left;$('timer-fill').style.width=(100*s.remaining/s.budget)+'%';$('countdown').classList.toggle('urgent',left<=7);$('timer-track').classList.toggle('urgent',left<=7);if(active&&left<=10&&!announcedTen){announcedTen=true;$('live-region').textContent=txt('เหลือ 10 วินาที','剩下 10 秒','10 seconds left');}}
function render(){
 const s=game.state,isStart=s.phase==='start',isEnding=s.phase==='ending';$('start-panel').hidden=!isStart;$('dialogue-panel').hidden=isStart||isEnding;$('ending-panel').hidden=!isEnding;$('mood-card').hidden=isStart||isEnding;$('pause-button').hidden=isStart||isEnding;$('pause-overlay').hidden=!paused||isStart||isEnding;
 document.querySelector('.stage').classList.toggle('academic-scene',!isStart&&!isEnding&&game.node()?.stage==='debrief');
 renderMeta();if(isStart)return;if(isEnding){renderEnding();return;}
 const n=game.node();if(renderedNodeId!==n.id){renderedNodeId=n.id;choiceOrder=shuffle(n.options.length);announcedTen=false;}
 $('academic-label').hidden=!n.academic;if(n.academic){const exam=D.nodes.filter(x=>x.academic);$('academic-label').textContent=`${ui('posttest')} · ${exam.findIndex(x=>x.id===n.id)+1} / ${exam.length} · ${tr(D.topics[n.topic])}`;}
 $('speaker-label').textContent=ui(n.npc+'Name');$('dialogue-text').textContent=emotionText(n);$('context-line').textContent=tr(n.context)+(n.academic?' · '+ui('examClock'):'');$('decision-count').textContent=`${ui('answered')} ${s.history.length} · ${s.repairId?txt('ทบทวนแผน','修正計畫','Plan review'):`${Math.min(s.index+1,D.nodes.length)} / ${D.nodes.length}`}`;
 $('choices').hidden=s.phase!=='choice';$('feedback').hidden=s.phase!=='feedback';
 if(s.phase==='choice'){$('choices').innerHTML=choiceOrder.map((actual,visible)=>`<button class="choice" type="button" data-choice="${visible}" aria-label="${visible+1}. ${escape(tr(n.options[actual].text))}"><span class="choice-num" aria-hidden="true">${visible+1}</span><span>${escape(tr(n.options[actual].text))}</span></button>`).join('');}
 else{
  const f=s.feedback;$('reaction-text').textContent=tr(f.option.reaction)+(f.option.explanation?' '+tr(f.option.explanation):'');$('feedback-symbol').textContent=f.timeout?'◷':(f.option.correctness===2?'♡':'✧');
  const items=[['safety',f.impact.safety,false],['trust',f.impact.trust,false],['tension',f.impact.stress,true]];$('impact-chips').innerHTML=items.filter(x=>x[1]).map(([key,value,invert])=>`<span class="impact-chip ${(invert?value>0:value<0)?'negative':''}">${ui(key)} ${value>0?'+':''}${value}</span>`).join('');
  if(f.timeout)$('impact-chips').insertAdjacentHTML('afterbegin',`<span class="impact-chip negative">${ui('responseExpired')}</span>`);
  if(n.academic)$('impact-chips').insertAdjacentHTML('afterbegin',`<span class="impact-chip ${f.option.correctness===2?'':'negative'}">${ui('knowledge')} ${f.option.correctness===2?'+1':'+0'} · ${s.knowledge.correct}/${s.knowledge.total}</span>`);
  $('learning-details').open=!!n.academic;$('learning-text').textContent=(n.academic?ui('correctAnswer')+': '+tr(n.options.find(o=>o.correctness===2).text)+'\n\n':'')+tr(n.lesson);$('learning-sources').innerHTML=(n.sources||[]).map(key=>`<a href="${escape(D.sources[key].url)}" target="_blank" rel="noopener noreferrer">${escape(D.sources[key].title)}</a>`).join('');
 }
 renderTimer();
}
function renderEnding(){
 const result=game.outcome(),end=D.endings[result.id],k=result.knowledge;
 const mentorMessage=k.correct>=10?txt('เราเชื่อมเหตุผลได้ดีมากแล้ว เวรหน้าลองนำความรู้นี้ไปอธิบายให้ทีมเข้าใจง่ายขึ้นนะ','你已能很好地串起理由，下次試著向團隊清楚說明。','You’re connecting the reasoning well. Next shift, practice explaining it clearly to the team.'):k.correct>=7?txt('มีหลายเรื่องที่เข้าใจดีแล้ว เราจะกลับไปอ่านหัวข้อที่ยังสับสน แล้วค่อยลองใช้กับเคสต่อไป','你已掌握不少重點，一起複習仍混淆的主題，再用到下一個案。','You understand several key points. Let’s revisit the uncertain topics before the next case.'):txt('พี่เห็นจุดที่จะช่วยติวแล้ว เริ่มจากหัวข้อข้างล่างทีละเรื่อง ไม่ต้องจำเฉลยอย่างเดียว ลองอธิบายว่าเพราะอะไร','我看到可以一起練習的地方了。從下方主題逐一開始，不只背答案，也練習說理由。','I can see where we can work together. Start with the topics below, one at a time. Practice the reason, not just the answer.');
 const topics=Object.entries(D.topics).map(([id,title])=>{const a=k.topics[id]||{correct:0,answered:0},total=D.nodes.filter(n=>n.academic&&n.topic===id).length;return`<li class="${a.correct===total?'mastered':'revisit'}"><span>${escape(tr(title))}</span><strong>${a.correct}/${total}</strong><small>${a.correct===total?txt('ตอบครบถูกต้อง','全部答對','All correct'):txt('ชวนทบทวน','建議複習','Revisit together')}</small></li>`;}).join('');
 $('ending-panel').innerHTML=`<span class="episode-label">${txt('บทสรุปเวรของ','班次總結：','SHIFT SUMMARY ·')} ${escape(prefs.name)}</span><div class="ending-icon" aria-hidden="true">${end.icon}</div><small class="result-label">${ui('caseResult')}</small><h2>${tr(end.title)}</h2><p>${tr(end.text)}</p><div class="ending-scores"><div class="ending-score"><strong>${result.safety}</strong><span>${ui('safety')}</span></div><div class="ending-score"><strong>${result.trust}</strong><span>${ui('trust')}</span></div><div class="ending-score"><strong>${result.timeouts}</strong><span>${ui('timeoutStat')}</span></div></div><section class="mentor-summary"><div class="mentor-summary-heading"><img src="assets/mentor-${moodFor('mentor')}.webp" alt="${ui('mentorName')}"><div><small>${ui('posttest')}</small><h3>${ui('knowledge')} <span>${k.correct}/${k.total}</span></h3></div></div><p>${mentorMessage}</p><p class="modal-note">${ui('knowledgeHint')} · ${txt('ความไว้ใจพี่เลี้ยง','前輩信任','Preceptor trust')} ${result.mentorTrust}/100</p><ul class="topic-results">${topics}</ul></section><p class="modal-note">${ui('scoreNote')}</p><details class="review-log"><summary>${ui('review')} · ${result.decisions}</summary>${game.state.history.map((h,i)=>{const n=D.nodes.find(n=>n.id===h.id),answer=h.academic?`<p class="review-answer">${ui('correctAnswer')}: ${escape(tr(n.options.find(o=>o.correctness===2).text))}</p>`:'';return`<div class="review-item"><strong>${i+1}. ${h.academic?escape(tr(D.topics[h.topic])):tr(D.scenes[h.scene].title)} ${h.correctness===2?'✓':'·'}</strong><span>${escape(tr(h.choice))}</span>${answer}<p>${escape(tr(h.lesson))}</p>${(h.sources||[]).map(key=>`<a href="${escape(D.sources[key].url)}" target="_blank" rel="noopener noreferrer">${escape(D.sources[key].title)}</a>`).join('')}</div>`;}).join('')}</details><div class="ending-actions"><button class="primary-btn" id="replay-button">${ui('replay')}</button><button class="secondary-btn" id="ending-reference">${ui('references')}</button></div>`;
}
async function start(){if(starting||game.state.phase!=='start')return;for(const id of ['player-name-input','student-code-input'])if(!$(id).value.trim()){$(id).reportValidity();$(id).focus();return;}prefs.studentCode=$('student-code-input').value.trim().slice(0,80);prefs.group=$('study-group-input').value.trim().slice(0,80);prefs.name=$('player-name-input').value.trim().slice(0,100);starting=true;accountState='ready';renderAccount();try{if(location.protocol!=='file:'){const r=await fetch('/api/participant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:prefs.name,studentCode:prefs.studentCode,group:prefs.group})});if(!r.ok)throw new Error();const check=await fetch('/api/me',{cache:'no-store'});if(!check.ok||!(await check.json()).participantReady)throw new Error();}savePrefs();game.start(+prefs.pace);history.start(prefs);history.capture(game,prefs,[]);paused=false;renderedNodeId=null;lastTick=performance.now();renderAvatar();render();focusChoice();}catch{accountState='error';}finally{starting=false;renderAccount();}}
function chooseVisible(index){if(blocked()||game.state.phase!=='choice')return;if(!Number.isInteger(index)||index<0||index>=choiceOrder.length)throw new Error('Invalid visible reply');game.choose(choiceOrder[index]);playAnswer();captureLog();$('learning-details').open=false;render();$('continue-button').focus({preventScroll:true});}
function next(){if(blocked()||game.state.phase!=='feedback')return;game.next();if(game.state.phase==='ending')history.capture(game,prefs,[]);lastTick=performance.now();render();if(game.state.phase==='ending')$('replay-button').focus({preventScroll:true});else focusChoice();}
function focusChoice(){document.querySelector('#choices button')?.focus({preventScroll:true});}
function pause(){if(!['choice','feedback'].includes(game.state.phase))return;paused=true;render();$('resume-button').focus({preventScroll:true});}
function resume(){paused=false;lastTick=performance.now();render();if(game.state.phase==='choice')focusChoice();else $('continue-button').focus({preventScroll:true});}
function changeLang(lang){if(!locales.includes(lang))throw new Error('Unsupported language');prefs.lang=lang;savePrefs();renderStatic();render();}
function configureLook(look,outfit){if(![0,1].includes(look)||![0,1,2].includes(outfit))throw new Error('Invalid appearance');prefs.look=look;prefs.outfit=outfit;savePrefs();renderSetup();}
$('language').addEventListener('change',e=>changeLang(e.target.value));$('start-game').addEventListener('click',start);$('continue-button').addEventListener('click',next);$('pause-button').addEventListener('click',pause);$('resume-button').addEventListener('click',resume);$('wardrobe-open').addEventListener('click',()=>openDialog('wardrobe-dialog'));$('notes-open').addEventListener('click',()=>openDialog('notes-dialog'));$('reference-open').addEventListener('click',()=>openDialog('reference-dialog'));
$('text-size').addEventListener('change',e=>{const value=+e.target.value;if(![100,125,150,175,200].includes(value))return;prefs.fontScale=value;applyTextSize();savePrefs();});
$('brand-home').addEventListener('click',e=>{e.preventDefault();if(game.state.phase==='start')return;if(game.state.phase==='ending'){game.reset();paused=false;renderedNodeId=null;render();}else openDialog('notes-dialog');});
$('history-open').addEventListener('click',openHistory);$('history-refresh').addEventListener('click',loadHistory);addEventListener('online',()=>history.flush());
document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;
 if(btn.dataset.choice!==undefined)chooseVisible(+btn.dataset.choice);
 if(btn.dataset.close){$(btn.dataset.close).close();lastTick=performance.now();}
 if(btn.dataset.pace){prefs.pace=+btn.dataset.pace;savePrefs();renderSetup();}
 if(btn.dataset.look!==undefined)configureLook(+btn.dataset.look,+prefs.outfit);
 if(btn.dataset.outfit!==undefined)configureLook(+prefs.look,+btn.dataset.outfit);
 if(btn.id==='replay-button'){game.reset();paused=false;renderedNodeId=null;renderStatic();render();$('start-game').focus({preventScroll:true});}
 if(btn.id==='ending-reference')openDialog('reference-dialog');
 if(btn.id==='notes-reference'){$('notes-dialog').close();openDialog('reference-dialog');}
 if(btn.dataset.run){selectedRun=btn.dataset.run;renderHistory();}
 if(btn.dataset.export)exportRuns(btn.dataset.export,btn.dataset.format);
});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{lastTick=performance.now();}));
document.addEventListener('keydown',e=>{if(blocked()||e.repeat||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(/^[123]$/.test(e.key)&&game.state.phase==='choice'){e.preventDefault();const i=+e.key-1;if(i<choiceOrder.length)chooseVisible(i);}else if(e.key==='Enter'&&game.state.phase==='feedback'&&e.target.tagName!=='SUMMARY'){e.preventDefault();next();}else if(e.key==='Escape'&&game.state.phase!=='start'&&game.state.phase!=='ending'){e.preventDefault();pause();}});
document.addEventListener('visibilitychange',()=>{lastTick=performance.now();audio.visibility(document.hidden);if(document.hidden&&['choice','feedback'].includes(game.state.phase))pause();});
setInterval(()=>{const now=performance.now(),elapsed=(now-lastTick)/1000;lastTick=now;if(blocked()||game.state.phase!=='choice')return;const previous=game.state.phase;game.tick(elapsed);if(previous!==game.state.phase){playAnswer();captureLog();render();$('continue-button').focus({preventScroll:true});}else renderTimer();},100);
function publicState(){const s=game.state,n=game.node();return{phase:s.phase,paused,language:prefs.lang,role:'new-pharmacist',appearance:{look:prefs.look,outfit:prefs.outfit},name:prefs.name,scene:n?.scene+1||D.scenes.length,remainingSeconds:Math.ceil(s.remaining),replyBudgetSeconds:s.budget,safety:s.safety,people:JSON.parse(JSON.stringify(s.people)),knowledge:JSON.parse(JSON.stringify(s.knowledge)),caseResult:s.caseResult?JSON.parse(JSON.stringify(s.caseResult)):null,decisions:s.history.length,node:n?.id||null,academic:!!n?.academic,replies:s.phase==='choice'?choiceOrder.map((actual,i)=>({replyIndex:i+1,text:tr(n.options[actual].text)})):[],outcome:s.phase==='ending'?game.outcome():null};}
// Structured actions share the same state and validation as the visible game.
const m=document.modelContext;if(m?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(m.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_pharmacist_game',description:'Read the current local game, visible reply choices and scores. Does not start or change a game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>publicState()});
 register({name:'start_pharmacist_shift',description:'Start a practice shift from the start screen. Requires a name and student ID, saves replies for instructor review, and does not require ChatGPT sign-in.',inputSchema:{type:'object',properties:{paceSeconds:{type:'integer',enum:[15,25,45]}},additionalProperties:false},execute:async input=>{if(game.state.phase!=='start')throw new Error('Return to the start screen before starting a shift');const pace=input?.paceSeconds??prefs.pace;if(![15,25,45].includes(pace))throw new Error('Invalid pace');prefs.pace=pace;await start();return publicState();}});
 register({name:'choose_pharmacist_reply',description:'Choose one currently visible reply by its one-based replyIndex. Changes local fictional scores and displays feedback; no real clinical action is taken.',inputSchema:{type:'object',properties:{replyIndex:{type:'integer',minimum:1,maximum:3}},required:['replyIndex'],additionalProperties:false},execute:input=>{if(game.state.phase!=='choice'||blocked())throw new Error('An unpaused choice must be visible');chooseVisible(input?.replyIndex-1);return publicState();}});
 register({name:'continue_pharmacist_dialogue',description:'Continue after visible feedback to the next local scene or ending.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{if(game.state.phase!=='feedback'||blocked())throw new Error('Unpaused feedback must be visible');next();return publicState();}});
 register({name:'configure_pharmacist_appearance',description:'Set the player’s local appearance and outfit using the same wardrobe controls.',inputSchema:{type:'object',properties:{look:{type:'integer',enum:[0,1]},outfit:{type:'integer',enum:[0,1,2]}},required:['look','outfit'],additionalProperties:false},execute:input=>{configureLook(input?.look,input?.outfit);return publicState();}});
 register({name:'set_pharmacist_language',description:'Change this game language to Thai, Traditional Chinese (Mandarin), or English. Preserves progress and time remaining.',inputSchema:{type:'object',properties:{language:{type:'string',enum:['th','zh','en']}},required:['language'],additionalProperties:false},execute:input=>{changeLang(input?.language);return publicState();}});
 addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
window.HEART_OF_CARE={read:publicState};renderStatic();render();
})();
